def transform(grid):
    # Each pair of diagonal rails around an expanding wedge encloses color 2.
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r in range(h):
        marks = [c for c, v in enumerate(grid[r]) if v != 0]
        # A single pair of rails expands one cell per row; fill strictly between.
        # Determine left/right endpoints by tracking diagonal marker lines.
        if len(marks) >= 2:
            for left, right in zip(marks, marks[1:]):
                if right - left > 1:
                    for c in range(left + 1, right):
                        out[r][c] = 2
    return out

